export interface WorkOSSeedOrganization {
  /**
   * Pinned organization id (e.g. `org_01ABC…`). Generated if omitted. Pin it to match
   * what your real WorkOS environment emits, so a backend whose database already
   * references a real org id lines up with the emulator across restarts.
   */
  id?: string;
  name: string;
  external_id?: string;
  metadata?: Record<string, string>;
  domains?: Array<{ domain: string; state?: 'verified' | 'pending' }>;
  allow_profiles_outside_organization?: boolean;
  /** Entitlement slugs minted into the `entitlements` claim of org-scoped access tokens. */
  entitlements?: string[];
  memberships?: Array<{
    /**
     * Email of a user defined in `users`. Seeded user ids are generated at startup,
     * so memberships are joined by email — an id literal could never resolve.
     */
    email: string;
    role?: string;
    status?: 'active' | 'inactive' | 'pending';
  }>;
  /**
   * AuthKit groups within this organization. Members reference a membership of this
   * org by the user's email — the same join key `memberships` use — because org
   * membership ids are generated at startup, so an id literal could never resolve.
   */
  groups?: Array<{
    name: string;
    description?: string | null;
    /** Emails of users that have a membership in this organization. */
    members?: string[];
  }>;
}

export interface WorkOSSeedUser {
  /**
   * Pinned user id (e.g. `user_01ABC…`). Generated if omitted. Pin it to match what your
   * real WorkOS environment emits, so the identity stays stable across emulator restarts
   * and can line up with an existing operator in a copied application database.
   */
  id?: string;
  email: string;
  name?: string;
  first_name?: string;
  last_name?: string;
  password?: string;
  email_verified?: boolean;
  external_id?: string;
  metadata?: Record<string, string>;
  impersonator?: { email: string; reason: string };
  /**
   * The OAuth provider this user authenticates with, reported as the authentication_method for
   * OAuth-based grants (authorization_code, refresh_token, device_code). Must be a spec-valid
   * value such as 'GoogleOAuth' or 'MicrosoftOAuth'. When omitted the emulator leaves
   * authentication_method off the response rather than guessing a provider.
   *
   * Setting it also links an OAuth identity, so the user is returned by
   * `GET /user_management/users/{id}/identities` and readable as `user.identities` in a JWT
   * template.
   */
  oauth_provider?: string;
  /**
   * The user's id at `oauth_provider`, reported as the linked identity's `idp_id`. Generated if
   * omitted. Pin it to match what your real WorkOS environment emits. Ignored without
   * `oauth_provider` — there is no identity to put it on.
   */
  oauth_idp_id?: string;
  /**
   * Enroll a TOTP authentication factor for this user at boot, exactly as
   * `POST /user_management/users/{id}/auth_factors` would. The factor is reported by
   * `GET /user_management/users/{id}/auth_factors`, and a password sign-in answers with the
   * spec's `mfa_challenge` step instead of a session — so MFA administration and step-up
   * login flows are testable without post-boot enrollment calls that in-memory state loses
   * on restart.
   */
  totp?: boolean;
}

export interface WorkOSSeedDirectory {
  name: string;
  /** Organization name, the same lookup key `connections` uses. */
  organization: string;
  /** Provider descriptor, e.g. `okta scim v2.0`. Free text, as the spec's list is open. */
  type?: string;
  state?: 'linked' | 'unlinked' | 'invalid_credentials';
  domain?: string;
  external_key?: string;
  /**
   * Directory groups. A bare string declares a group with no role mapping; the object form
   * maps the group to an organization role, the way a directory's role assignments do in
   * the dashboard.
   */
  groups?: Array<string | { name: string; role?: string }>;
  users?: Array<{
    email: string;
    first_name?: string;
    last_name?: string;
    username?: string;
    idp_id?: string;
    state?: 'active' | 'inactive';
    /** Names from this directory's `groups`. */
    groups?: string[];
    /** Overrides the role mapped from `groups`. */
    role?: string;
    custom_attributes?: Record<string, unknown>;
  }>;
}

export interface WorkOSSeedConnection {
  name: string;
  connection_type?: WorkOSConnectionType;
  organization: string;
  state?: 'active' | 'inactive' | 'validating';
  domains?: string[];
  profiles?: Array<{
    email: string;
    first_name?: string;
    last_name?: string;
    idp_id?: string;
    groups?: string[];
  }>;
}

export interface WorkOSSeedPipeConnection {
  user_id: string;
  provider: PipeProvider;
  scopes: string[];
  status?: PipeConnectionStatus;
  external_account_id?: string;
}

export interface WorkOSSeedConnectedAccount {
  /**
   * Email of a user defined in `users` — the same join key memberships use, because seeded
   * user ids are generated at startup unless pinned.
   */
  email: string;
  /** Provider slug the account is addressed by in the API path (`github`, `slack`, `notion`, …). */
  provider: string;
  /**
   * Name of an organization defined in `organizations`, for a connection scoped to one.
   * Lookups filter by `?organization_id=…`: a user's lone account for a provider resolves
   * without it, while several scoped ones must name theirs, matching the API's 409.
   */
  organization?: string;
  /** OAuth scopes granted for the connection. */
  scopes?: string[];
  /**
   * Defaults to `connected` — saying a user has a connected account is saying it is
   * connected. `disconnected` is not seedable: a disconnected account is a deleted one,
   * observable only in the event stream.
   */
  state?: ConnectedAccountState;
}

export interface WorkOSSeedInvitation {
  email: string;
  organization_id?: string;
  inviter_user_id?: string;
  role_slug?: string;
}

export interface WorkOSSeedRole {
  slug: string;
  name: string;
  description?: string;
  type?: 'EnvironmentRole' | 'OrganizationRole';
  organization_id?: string;
  is_default_role?: boolean;
  priority?: number;
  permissions?: string[];
  resource_type_slug?: string;
}

export interface WorkOSSeedPermission {
  slug: string;
  name: string;
  description?: string;
  resource_type_slug?: string;
}

export interface WorkOSSeedWebhookEndpoint {
  endpoint_url?: string;
  /** @deprecated Use endpoint_url */
  url?: string;
  events?: string[];
  enabled?: boolean;
  /**
   * Pinned signing secret. Generated if omitted. Pin it to bake the secret into a
   * consumer's environment, so it can verify `WorkOS-Signature` headers on seeded
   * deliveries without first discovering the secret via `GET /webhook_endpoints`.
   */
  secret?: string;
}

export interface WorkOSSeedConnectApplication {
  name: string;
  /** Application type. Defaults to `m2m`. */
  type?: 'm2m' | 'oauth';
  /** Owning organization, by name. Required for `m2m` applications. */
  organization?: string;
  description?: string;
  /** OAuth scopes granted to the application. */
  scopes?: string[];
  /**
   * The `aud` claim minted into this app's m2m tokens. Defaults to the client_id.
   * Pin it to match what your real WorkOS environment emits, so a JWKS consumer that
   * validates `aud` accepts emulator tokens unchanged.
   */
  audience?: string;
  /** Pinned client_id. Generated (`client_...`) if omitted. */
  client_id?: string;
  /**
   * Pinned client secret value. Generated (`secret_...`) if omitted. Stored as a
   * client_secret resource so the seeded application has usable credentials. Pin it
   * to bake a known secret into a service's environment.
   */
  client_secret?: string;
  /** OAuth redirect URIs. Ignored for `m2m` applications. */
  redirect_uris?: string[];
  /**
   * `oauth` only. A third-party application (`false`) is reported with the organization it
   * belongs to, so `organization` is required for one. Defaults to `true`.
   */
  is_first_party?: boolean;
  /** `oauth` only. Reported on the application; the emulator does not enforce PKCE from it. */
  uses_pkce?: boolean;
  /** Emulator-only Standalone Connect login page, receiving an external_auth_id. */
  login_url?: string | null;
}

export interface WorkOSSeedApiKey {
  name: string;
  /** Owning organization, by name. Required unless `user_id` is set. */
  organization?: string;
  /** Owning user, by id. When set, `organization` supplies the required organization_id. */
  user_id?: string;
  /**
   * Pinned secret value. Must start with `sk_` to be accepted for authentication.
   * Generated (`sk_test_...`) if omitted.
   */
  value?: string;
  /** Permission slugs assigned to the key. */
  permissions?: string[];
  /** Expiry timestamp (ISO 8601), or null for a key that never expires. */
  expires_at?: string | null;
  /** Auth environment. Defaults to `production` for `sk_live_*` values, else `test`. */
  environment?: string;
}

/** Legacy auth allow-list: maps a raw API key value to its environment. */
export type WorkOSSeedApiKeyAuthMap = Record<string, { environment: string }>;

export interface WorkOSSeedFeatureFlag {
  /**
   * Pinned flag id (e.g. `flag_01ABC…`). Generated if omitted. Pin it to match what your
   * real WorkOS environment emits, so an application storing flag ids lines up across
   * emulator restarts.
   */
  id?: string;
  /**
   * The key application code references. Required, unique within the environment, and URL-safe:
   * every route addresses a flag by slug in the path.
   */
  slug: string;
  /** Display name. Defaults to the slug. */
  name?: string;
  description?: string | null;
  /** Whether the flag is active in this environment at all. Defaults to true. */
  enabled?: boolean;
  /**
   * Value for users and organizations matching no target — the flag's "on for everyone"
   * switch. Defaults to false, so a flag with targets is on for exactly those targets.
   */
  default_value?: boolean;
  /** Labels the dashboard filters by. Purely descriptive. */
  tags?: string[];
  owner?: { email: string; first_name?: string | null; last_name?: string | null };
  /**
   * Resources the flag is switched on for regardless of `default_value`. Targeting is
   * additive, as it is in production: a target can turn a flag on but never off.
   */
  targets?: {
    /**
     * Emails of users defined in `users`. Seeded user ids are generated at startup, so
     * targets are joined by email — an id literal could never resolve.
     */
    users?: string[];
    /** Names of organizations defined in `organizations`, joined the same way. */
    organizations?: string[];
  };
}

export interface WorkOSSeedAgentBlueprint {
  /** Pinned blueprint id (e.g. `agent_blueprint_01ABC…`). Generated if omitted. */
  id?: string;
  /** Required and unique within the environment, as production enforces on create. */
  name: string;
  /** 1 to 1000 characters. Omit for no description, as production's create endpoint requires. */
  description?: string;
  /** Slugs of permissions defined in `permissions`; the ceiling on what a minted session may hold. */
  permissions?: string[];
  invocable_by?: {
    /** Slugs of roles defined in `roles`. Empty or omitted lets any member mint a delegated session. */
    role_slugs?: string[];
    /**
     * Names of organizations defined in `organizations`, joined by name for the same reason
     * feature-flag targets are. Empty or omitted lets every organization invoke the blueprint.
     */
    organizations?: string[];
  };
  /**
   * All three are required when the object is given, as on production's create endpoint.
   * Omitting the object uses production's defaults: 3600 / 300 / 3600 seconds.
   */
  session_settings?: {
    max_age_seconds: number;
    access_token_ttl_seconds: number;
    refresh_token_ttl_seconds: number;
  };
}

export interface WorkOSSeedJwtTemplate {
  /**
   * Template string rendering to a JSON object of claims, e.g.
   * `'{"urn:myapp:tenant": "{{ organization.metadata.tenant_id }}"}'`. Validated at
   * startup, so a malformed template fails the boot rather than the first sign-in.
   */
  content: string;
}

export interface WorkOSSeedConfig {
  organizations?: WorkOSSeedOrganization[];
  users?: WorkOSSeedUser[];
  connections?: WorkOSSeedConnection[];
  pipeConnections?: WorkOSSeedPipeConnection[];
  /** Pipes connected accounts, served by `/user_management/users/{id}/connected_accounts/{slug}`. */
  connectedAccounts?: WorkOSSeedConnectedAccount[];
  invitations?: WorkOSSeedInvitation[];
  roles?: WorkOSSeedRole[];
  permissions?: WorkOSSeedPermission[];
  webhookEndpoints?: WorkOSSeedWebhookEndpoint[];
  connectApplications?: WorkOSSeedConnectApplication[];
  /**
   * API keys. Either the legacy auth allow-list map (value → environment) or an array
   * of API key resources. The array form creates `api_key` records AND registers each
   * value in the auth allow-list so the seeded key authenticates requests.
   */
  apiKeys?: WorkOSSeedApiKeyAuthMap | WorkOSSeedApiKey[];
  /**
   * The environment's JWT template, whose claims are merged into every access token the
   * emulator mints. Seeding it means a test suite gets custom claims without a setup call.
   */
  jwtTemplate?: WorkOSSeedJwtTemplate;
  /**
   * Feature flags and their targets. Production has no create-flag endpoint — flags are
   * made in the dashboard — so seeding is the only way to get one into the emulator.
   */
  featureFlags?: WorkOSSeedFeatureFlag[];
  /**
   * Directories, their groups and their users. Production has no create-directory
   * endpoint — a directory is connected through the dashboard or Admin Portal — so
   * seeding is the only way to get one into the emulator.
   */
  directories?: WorkOSSeedDirectory[];
  /**
   * Agent blueprints, so a test suite can mint agent tokens without a create call. Instances
   * and sessions are never seeded: they only come into being by minting.
   */
  agentBlueprints?: WorkOSSeedAgentBlueprint[];
}

export function seedFromConfig(store: Store, _baseUrl: string, config: WorkOSSeedConfig): void {
  // Validate the config before seeding
  const validation = validateSeedConfig(config);
  if (!validation.valid) {
    throw new Error(`Invalid seed configuration:\n${formatValidationErrors(validation.errors)}`);
  }

  const ws = getWorkOSStore(store);

  if (config.users) {
    for (const userConfig of config.users) {
      const user = ws.users.insert({
        object: 'user',
        id: userConfig.id,
        // Trimmed, as both routes that create users store it: a padded seed would otherwise be
        // written under a spelling no lookup by email resolves. validateSeedConfig normalizes the
        // same way, so what it cross-referenced is what lands here.
        email: userConfig.email.trim(),
        name: userConfig.name ?? null,
        first_name: userConfig.first_name ?? null,
        last_name: userConfig.last_name ?? null,
        email_verified: userConfig.email_verified ?? false,
        profile_picture_url: null,
        last_sign_in_at: null,
        external_id: userConfig.external_id ?? null,
        metadata: userConfig.metadata ?? {},
        locale: null,
        password_hash: userConfig.password ? hashPassword(userConfig.password) : null,
        impersonator: userConfig.impersonator ?? null,
        oauth_provider: userConfig.oauth_provider ?? null,
      });

      // Being told a user authenticates with an OAuth provider is being told they have a linked
      // identity: it is the same fact `GET /user_management/users/{id}/identities` reports, so a
      // seed that sets one no longer has to also be an account with no identities at all.
      if (userConfig.oauth_provider) {
        linkOAuthIdentity(
          ws,
          user.id,
          userConfig.oauth_provider,
          userConfig.oauth_idp_id ?? `idp_${generateId('usr')}`,
        );
      }

      // The same record the enrollment route writes, so ListAuthFactors reports it and the
      // password grant challenges it like any enrolled second factor.
      if (userConfig.totp) {
        ws.authFactors.insert({
          object: 'authentication_factor',
          user_id: user.id,
          type: 'totp',
          totp: newTotp('WorkOS Emulator', user.email),
        });
      }
    }
  }

  if (config.organizations) {
    for (const orgConfig of config.organizations) {
      const org = ws.organizations.insert({
        object: 'organization',
        id: orgConfig.id,
        name: orgConfig.name,
        external_id: orgConfig.external_id ?? null,
        metadata: orgConfig.metadata ?? {},
        stripe_customer_id: null,
        allow_profiles_outside_organization: orgConfig.allow_profiles_outside_organization ?? false,
        entitlements: orgConfig.entitlements ?? [],
      });

      syncOrganizationResource(ws, org);

      if (orgConfig.domains) {
        for (const dd of orgConfig.domains) {
          ws.organizationDomains.insert({
            object: 'organization_domain',
            organization_id: org.id,
            domain: dd.domain,
            state: dd.state ?? 'pending',
            verification_strategy: 'manual',
            verification_token: generateVerificationToken(),
            verification_prefix: 'workos-verify',
          });
        }
      }

      if (orgConfig.memberships) {
        for (const mm of orgConfig.memberships) {
          // Memberships reference seeded users by email: user ids are generated at
          // insert time, so an id literal in a config could never resolve, and a
          // dangling membership would break membership serialization (which requires
          // a resolvable embedded user). validateSeedConfig guarantees the reference
          // matches a seeded user — case-insensitively, as it does here.
          const memberUser = findUserByEmail(ws, mm.email);
          if (!memberUser) {
            throw new Error(`Seed membership references unknown user '${mm.email}' (organization '${orgConfig.name}')`);
          }
          ws.organizationMemberships.insert({
            object: 'organization_membership',
            organization_id: org.id,
            user_id: memberUser.id,
            role: { slug: mm.role ?? 'member' },
            status: mm.status ?? 'active',
            external_id: null,
            metadata: {},
          });
        }
      }

      if (orgConfig.groups) {
        for (const gg of orgConfig.groups) {
          const group = ws.groups.insert({
            object: 'group',
            organization_id: org.id,
            name: gg.name,
            description: gg.description ?? null,
          });

          if (gg.members) {
            for (const memberEmail of gg.members) {
              // Group members reference an org membership by the user's email — the
              // same join key memberships use. validateSeedConfig guarantees the email
              // matches a membership of this org; resolving the user then the membership
              // here is the lookup that turns that guarantee into a join row.
              const memberUser = findUserByEmail(ws, memberEmail);
              if (!memberUser) {
                throw new Error(
                  `Seed group '${gg.name}' references unknown user '${memberEmail}' (organization '${orgConfig.name}')`,
                );
              }
              const membership = ws.organizationMemberships
                .findBy('organization_id', org.id)
                .find((m) => m.user_id === memberUser.id);
              if (!membership) {
                throw new Error(
                  `Seed group '${gg.name}' member '${memberEmail}' has no membership in organization '${orgConfig.name}'`,
                );
              }
              ws.groupMemberships.insert({
                group_id: group.id,
                organization_membership_id: membership.id,
              });
            }
          }
        }
      }
    }
  }

  if (config.connections) {
    for (const connConfig of config.connections) {
      const org = ws.organizations.findOneBy('name', connConfig.organization);
      if (!org) continue;

      const domains = (connConfig.domains ?? []).map((d) => ({
        object: 'connection_domain' as const,
        id: generateId('conn_domain'),
        domain: d,
      }));

      const conn = ws.connections.insert({
        object: 'connection',
        organization_id: org.id,
        connection_type: connConfig.connection_type ?? 'GenericSAML',
        name: connConfig.name,
        state: connConfig.state ?? 'active',
        domains,
      });

      if (connConfig.profiles) {
        for (const p of connConfig.profiles) {
          ws.ssoProfiles.insert({
            object: 'profile',
            connection_id: conn.id,
            connection_type: conn.connection_type,
            organization_id: org.id,
            idp_id: p.idp_id ?? `idp_${generateId('usr')}`,
            email: p.email,
            first_name: p.first_name ?? null,
            last_name: p.last_name ?? null,
            groups: p.groups ?? [],
            raw_attributes: { email: p.email },
          });
        }
      }
    }
  }

  if (config.directories) {
    // First declaration wins: two directories in one organization can list the same
    // person, and last-write-wins would make their access depend on array order.
    const rolesApplied = new Set<string>();
    for (const dirConfig of config.directories) {
      const org = ws.organizations.findOneBy('name', dirConfig.organization);
      if (!org) continue;

      const directory = ws.directories.insert({
        object: 'directory',
        organization_id: org.id,
        name: dirConfig.name,
        domain: dirConfig.domain ?? null,
        type: dirConfig.type ?? 'generic scim v2.0',
        state: dirConfig.state ?? 'linked',
        external_key: dirConfig.external_key ?? null,
      });

      // Groups are inserted first: a seeded user embeds the groups it belongs to, and the
      // embedded copy carries the generated id, so the group must exist to be joined.
      const groupsByName = new Map<string, WorkOSDirectoryGroup>();
      // Declaration order is the mapping's priority order — see roleForGroups below.
      const roleByGroupName = new Map<string, string>();
      const declaredGroups: string[] = [];
      for (const entry of dirConfig.groups ?? []) {
        const groupName = typeof entry === 'string' ? entry : entry.name;
        const mappedRole = typeof entry === 'string' ? undefined : entry.role;
        declaredGroups.push(groupName);
        if (mappedRole) roleByGroupName.set(groupName, mappedRole);
        groupsByName.set(
          groupName,
          ws.directoryGroups.insert({
            object: 'directory_group',
            directory_id: directory.id,
            organization_id: org.id,
            idp_id: `idp_${generateId('dir_grp')}`,
            name: groupName,
            raw_attributes: {},
          }),
        );
      }

      /**
       * The role a directory's group mapping resolves to. A user in several mapped groups
       * takes the first in declaration order, which is the emulator's stand-in for the
       * dashboard's role-assignment priority.
       */
      const roleForGroups = (memberOf: string[]): string | undefined => {
        const mapped = declaredGroups.find((name) => memberOf.includes(name) && roleByGroupName.has(name));
        return mapped ? roleByGroupName.get(mapped) : undefined;
      };

      for (const u of dirConfig.users ?? []) {
        const role = u.role ?? roleForGroups(u.groups ?? []);
        const memberships = (u.groups ?? []).map((groupName) => {
          const group = groupsByName.get(groupName);
          if (!group) {
            throw new Error(
              `Seed directory '${dirConfig.name}' user '${u.email}' references unknown group '${groupName}'`,
            );
          }
          return { object: 'directory_group' as const, id: group.id, name: group.name };
        });

        ws.directoryUsers.insert({
          object: 'directory_user',
          directory_id: directory.id,
          organization_id: org.id,
          idp_id: u.idp_id ?? `idp_${generateId('dir_usr')}`,
          first_name: u.first_name ?? null,
          last_name: u.last_name ?? null,
          email: u.email.trim(),
          username: u.username ?? null,
          state: u.state ?? 'active',
          role: role ? { slug: role } : null,
          custom_attributes: u.custom_attributes ?? {},
          raw_attributes: { email: u.email.trim() },
          groups: memberships,
        });

        // Production resolves the mapping and stamps the role on the organization
        // membership, which is what an app reads — the directory user is only the record it
        // was derived from. Seeding a directory provisions no AuthKit user, so this applies
        // only where `users` and `memberships` already put one in the org.
        const authKitUser = findUserByEmail(ws, u.email);
        const membership = authKitUser ? liveMembershipFor(ws, org.id, authKitUser.id) : undefined;
        if (membership) {
          // Write only what changes: a later directory re-listing an already-managed person
          // with no role to give would otherwise bump `updated_at` and emit an
          // `organization_membership.updated` that says nothing.
          const updates: Partial<WorkOSOrganizationMembership> = {};
          if (!membership.directory_managed) updates.directory_managed = true;
          if (role && !rolesApplied.has(membership.id)) {
            rolesApplied.add(membership.id);
            updates.role = { slug: role };
          }
          if (Object.keys(updates).length > 0) ws.organizationMemberships.update(membership.id, updates);
        }
      }
    }
  }

  if (config.pipeConnections) {
    for (const pc of config.pipeConnections) {
      ws.pipeConnections.insert({
        object: 'pipe_connection',
        user_id: pc.user_id,
        provider: pc.provider,
        scopes: pc.scopes,
        status: pc.status ?? 'connected',
        external_account_id: pc.external_account_id ?? null,
      });
    }
  }

  if (config.connectedAccounts) {
    for (const ca of config.connectedAccounts) {
      // Both references were cross-checked by validateSeedConfig against this same config,
      // so they resolve; the guards only keep a future validator gap from crashing startup.
      const user = findUserByEmail(ws, ca.email);
      if (!user) continue;
      const org = ca.organization ? ws.organizations.findOneBy('name', ca.organization) : undefined;
      if (ca.organization && !org) continue;
      ws.connectedAccounts.insert({
        object: 'connected_account',
        user_id: user.id,
        organization_id: org?.id ?? null,
        provider: ca.provider,
        data_integration_id: dataIntegrationIdFor(ws, ca.provider),
        scopes: ca.scopes ?? [],
        auth_method: 'oauth',
        api_key_last_4: null,
        state: ca.state ?? 'connected',
        access_token: null,
        refresh_token: null,
        token_expires_at: null,
      });
    }
  }

  if (config.permissions) {
    for (const permConfig of config.permissions) {
      ws.permissions.insert({
        object: 'permission',
        slug: permConfig.slug,
        name: permConfig.name,
        description: permConfig.description ?? null,
        resource_type_slug: permConfig.resource_type_slug ?? DEFAULT_RESOURCE_TYPE_SLUG,
      });
    }
  }

  if (config.roles) {
    for (const roleConfig of config.roles) {
      const role = ws.roles.insert({
        object: 'role',
        slug: roleConfig.slug,
        name: roleConfig.name,
        description: roleConfig.description ?? null,
        type: roleConfig.type ?? 'EnvironmentRole',
        organization_id: roleConfig.organization_id ?? null,
        is_default_role: roleConfig.is_default_role ?? false,
        priority: roleConfig.priority ?? 0,
        resource_type_slug: roleConfig.resource_type_slug ?? DEFAULT_RESOURCE_TYPE_SLUG,
      });

      if (roleConfig.permissions) {
        for (const permSlug of roleConfig.permissions) {
          const perm = ws.permissions.findOneBy('slug', permSlug);
          if (perm) {
            ws.rolePermissions.insert({ role_id: role.id, permission_id: perm.id });
          }
        }
      }
    }
  }

  if (config.invitations) {
    for (const invConfig of config.invitations) {
      const token = generateVerificationToken();
      ws.invitations.insert({
        object: 'invitation',
        email: invConfig.email.trim(),
        state: 'pending',
        token,
        accept_invitation_url: `${_baseUrl}/user_management/invitations/accept?token=${token}`,
        organization_id: invConfig.organization_id ?? null,
        inviter_user_id: invConfig.inviter_user_id ?? null,
        role_slug: invConfig.role_slug ?? null,
        expires_at: expiresIn(72 * 60),
        accepted_at: null,
        revoked_at: null,
        accepted_user_id: null,
      });
    }
  }

  if (config.webhookEndpoints) {
    for (const whConfig of config.webhookEndpoints) {
      const endpointUrl = whConfig.endpoint_url ?? whConfig.url;
      if (!endpointUrl || typeof endpointUrl !== 'string') {
        throw new Error('workos seed config: webhookEndpoints[].endpoint_url is required');
      }
      ws.webhookEndpoints.insert({
        object: 'webhook_endpoint',
        endpoint_url: endpointUrl,
        secret: whConfig.secret ?? randomBytes(32).toString('hex'),
        enabled: whConfig.enabled !== false,
        events: whConfig.events ?? [],
        description: null,
      });
    }
  }

  if (config.connectApplications) {
    for (const appConfig of config.connectApplications) {
      const type = appConfig.type ?? 'm2m';
      const isFirstParty = appConfig.is_first_party ?? true;
      const org = appConfig.organization ? ws.organizations.findOneBy('name', appConfig.organization) : undefined;
      // An m2m application must be tied to a real organization, and so must a third-party
      // oauth one — the spec requires `organization_id` on both. A name that does not resolve
      // would otherwise seed an app with a null owner, the shape the create route rejects.
      if ((type === 'm2m' || !isFirstParty) && !org) {
        throw new Error(
          `workos seed config: connectApplications[].organization not found: ${JSON.stringify(appConfig.organization)}`,
        );
      }

      const application = ws.connectApplications.insert({
        object: 'connect_application',
        name: appConfig.name,
        description: appConfig.description ?? null,
        application_type: type,
        organization_id: org?.id ?? null,
        scopes: appConfig.scopes ?? [],
        audience: appConfig.audience ?? null,
        redirect_uris: appConfig.redirect_uris ?? [],
        is_first_party: isFirstParty,
        // Seeding is the dashboard's stand-in, and dynamic client registration is a runtime
        // act no seed file performs.
        was_dynamically_registered: false,
        uses_pkce: appConfig.uses_pkce ?? false,
        login_url: appConfig.login_url ?? null,
        client_id: appConfig.client_id ?? generateClientId(),
        logo_url: null,
      });

      // Always provision a client secret so the seeded app has usable credentials.
      const secretValue = appConfig.client_secret ?? `secret_${generateVerificationToken()}`;
      ws.clientSecrets.insert({
        object: 'connect_application_secret',
        application_id: application.id,
        value: secretValue,
        secret_hint: secretValue.slice(-4),
        last_used_at: null,
      });
    }
  }

  // The array form seeds API key resources; the map form is the legacy auth allow-list
  // handled at server creation (see createEmulator), so it is skipped here.
  if (Array.isArray(config.apiKeys)) {
    const authMap = store.getData<ApiKeyMap>(STORE_KEYS.apiKeyMap) ?? {};
    for (const keyConfig of config.apiKeys) {
      const value = keyConfig.value ?? `sk_test_${generateVerificationToken()}`;
      const environment = keyConfig.environment ?? (value.startsWith('sk_live_') ? 'production' : 'test');
      const org = keyConfig.organization ? ws.organizations.findOneBy('name', keyConfig.organization) : undefined;
      // The owner organization must resolve; otherwise the key would be created with an
      // empty owner id yet still authenticate requests (config validation guarantees the
      // `organization` field is present for both org- and user-owned keys).
      if (keyConfig.organization && !org) {
        throw new Error(
          `workos seed config: apiKeys[].organization not found: ${JSON.stringify(keyConfig.organization)}`,
        );
      }

      const owner: WorkOSApiKeyOwner = keyConfig.user_id
        ? { type: 'user', id: keyConfig.user_id, organization_id: org?.id ?? '' }
        : { type: 'organization', id: org?.id ?? '' };

      const expiresAt = keyConfig.expires_at ?? null;
      ws.apiKeyRecords.insert({
        object: 'api_key',
        name: keyConfig.name,
        key: value,
        environment,
        owner,
        permissions: keyConfig.permissions ?? [],
        last_used_at: null,
        expires_at: expiresAt,
      });

      // Register the value in the shared auth allow-list (the same object the auth
      // middleware holds by reference) so the seeded key authenticates real requests.
      // The expiry travels with the entry; the middleware (and validations) reject the
      // key once it is past, so both an already-expired key and one that lapses later
      // stop authenticating — matching production.
      authMap[value] = { environment, expiresAt };
    }
    store.setData(STORE_KEYS.apiKeyMap, authMap);
  }

  // Seeded last: targets join to users by email and organizations by name, so both must
  // already be in the store.
  if (config.featureFlags) {
    for (const flagConfig of config.featureFlags) {
      const flag = ws.featureFlags.insert({
        object: 'feature_flag',
        id: flagConfig.id,
        slug: flagConfig.slug,
        name: flagConfig.name ?? flagConfig.slug,
        description: flagConfig.description ?? null,
        owner: flagConfig.owner
          ? {
              // Trimmed, as seeded user emails are: the validator cross-references the trimmed
              // form, so storing the padded one would serve an address it never checked.
              email: flagConfig.owner.email.trim(),
              first_name: flagConfig.owner.first_name ?? null,
              last_name: flagConfig.owner.last_name ?? null,
            }
          : null,
        tags: flagConfig.tags ?? [],
        enabled: flagConfig.enabled !== false,
        default_value: flagConfig.default_value ?? false,
      });

      // Deduped the way the create-target route is: two rows for one resource would leave the
      // flag on for a resource whose target was removed, since DELETE drops only the first match.
      const targeted = new Set<string>();
      const addTarget = (resourceId: string, resourceType: 'user' | 'organization') => {
        if (targeted.has(resourceId)) return;
        targeted.add(resourceId);
        ws.flagTargets.insert({
          object: 'flag_target',
          flag_slug: flag.slug,
          resource_id: resourceId,
          resource_type: resourceType,
          enabled: true,
        });
      };

      for (const email of flagConfig.targets?.users ?? []) {
        const user = findUserByEmail(ws, email);
        if (!user) {
          throw new Error(
            `workos seed config: featureFlags[${JSON.stringify(flagConfig.slug)}].targets.users not found: ${JSON.stringify(email)}`,
          );
        }
        addTarget(user.id, 'user');
      }

      for (const name of flagConfig.targets?.organizations ?? []) {
        const org = ws.organizations.findOneBy('name', name);
        if (!org) {
          throw new Error(
            `workos seed config: featureFlags[${JSON.stringify(flagConfig.slug)}].targets.organizations not found: ${JSON.stringify(name)}`,
          );
        }
        addTarget(org.id, 'organization');
      }
    }
  }

  // After permissions, roles and organizations, which every reference here resolves against.
  if (config.agentBlueprints) {
    for (const blueprintConfig of config.agentBlueprints) {
      const organizationIds = (blueprintConfig.invocable_by?.organizations ?? []).map((name) => {
        const org = ws.organizations.findOneBy('name', name);
        if (!org) {
          throw new Error(
            `workos seed config: agentBlueprints[${JSON.stringify(blueprintConfig.name)}].invocable_by.organizations not found: ${JSON.stringify(name)}`,
          );
        }
        return org.id;
      });
      ws.agentBlueprints.insert({
        object: 'agent_blueprint',
        id: blueprintConfig.id,
        name: blueprintConfig.name,
        description: blueprintConfig.description ?? null,
        permissions: [...new Set(blueprintConfig.permissions ?? [])],
        invocable_by: {
          role_slugs: [...new Set(blueprintConfig.invocable_by?.role_slugs ?? [])],
          organization_ids: [...new Set(organizationIds)],
        },
        session_settings: blueprintConfig.session_settings ?? { ...DEFAULT_AGENT_SESSION_SETTINGS },
      });
    }
  }

  if (config.jwtTemplate) {
    const problems = validateJwtTemplateContent(config.jwtTemplate.content);
    if (problems.length > 0) {
      throw new Error(`workos seed config: jwtTemplate.content is invalid: ${problems.join('; ')}`);
    }
    const now = new Date().toISOString();
    store.setData(STORE_KEYS.jwtTemplate, {
      object: 'jwt_template',
      content: config.jwtTemplate.content,
      created_at: now,
      updated_at: now,
    } satisfies WorkOSJwtTemplate);
  }
}

export const workosPlugin: ServicePlugin = {
  name: 'workos',
  register(ctx: RouteContext): void {
    organizationRoutes(ctx);
    organizationDomainRoutes(ctx);
    membershipRoutes(ctx);
    groupRoutes(ctx);
    userRoutes(ctx);
    emailVerificationRoutes(ctx);
    passwordResetRoutes(ctx);
    magicAuthRoutes(ctx);
    authFactorRoutes(ctx);
    sessionRoutes(ctx);
    authRoutes(ctx);
    connectionRoutes(ctx);
    ssoRoutes(ctx);
    pipeRoutes(ctx);
    connectedAccountRoutes(ctx);
    invitationRoutes(ctx);
    configRoutes(ctx);
    userFeatureRoutes(ctx);
    widgetRoutes(ctx);
    authorizationRoleRoutes(ctx);
    authorizationPermissionRoutes(ctx);
    authorizationOrgRoleRoutes(ctx);
    authorizationResourceRoutes(ctx);
    authorizationCheckRoutes(ctx);
    portalRoutes(ctx);
    legacyMfaRoutes(ctx);
    apiKeyRoutes(ctx);
    vaultRoutes(ctx);
    radarRoutes(ctx);
    connectRoutes(ctx);
    clientApiRoutes(ctx);
    oauthRoutes(ctx);
    standaloneConnectRoutes(ctx);
    directoryRoutes(ctx);
    auditLogRoutes(ctx);
    featureFlagRoutes(ctx);
    agentRoutes(ctx);
    dataIntegrationRoutes(ctx);
    webhookEndpointRoutes(ctx);
    eventRoutes(ctx);

    // Set up event bus with collection hooks (Option A from spec)
    // Store on ctx.store for route-level access (hybrid Option A+B for action events)
    // Check for webhook retry config in store data (set by emulator options)
    const webhookRetryConfig = ctx.store.getData<any>('webhookRetryConfig');
    const webhookDebugMode = ctx.store.getData<boolean>('webhookDebugMode') ?? false;

    const eventBus = new EventBus(ctx.store, {
      retryConfig: webhookRetryConfig,
      debugMode: webhookDebugMode,
    });
    ctx.store.setData(STORE_KEYS.eventBus, eventBus);
    const ws = getWorkOSStore(ctx.store);

    ws.users.setHooks({
      onInsert: (u) => eventBus.emit({ event: EVENTS.userCreated, data: formatUser(u) }),
      onUpdate: (u) => eventBus.emit({ event: EVENTS.userUpdated, data: formatUser(u) }),
      onDelete: (u) => eventBus.emit({ event: EVENTS.userDeleted, data: formatUser(u) }),
    });
    // The organization's own events occur within it: `data` is the organization, so its id is
    // the scope, not a `data.organization_id`.
    const organizationEvent = (event: string) => (o: WorkOSOrganization) =>
      eventBus.emit({ event, data: formatOrganization(o, ws), organization_id: o.id });
    ws.organizations.setHooks({
      onInsert: organizationEvent(EVENTS.organizationCreated),
      onUpdate: organizationEvent(EVENTS.organizationUpdated),
      onDelete: organizationEvent(EVENTS.organizationDeleted),
    });
    ws.organizationDomains.setHooks({
      onInsert: (d) => eventBus.emit({ event: EVENTS.organizationDomainCreated, data: formatDomain(d) }),
      onUpdate: (d) =>
        eventBus.emit({
          event: d.state === 'verified' ? EVENTS.organizationDomainVerified : EVENTS.organizationDomainUpdated,
          data: formatDomain(d),
        }),
      onDelete: (d) => eventBus.emit({ event: EVENTS.organizationDomainDeleted, data: formatDomain(d) }),
    });
    ws.organizationMemberships.setHooks({
      onInsert: (m) => eventBus.emit({ event: EVENTS.organizationMembershipCreated, data: formatMembershipEvent(m) }),
      onUpdate: (m) => eventBus.emit({ event: EVENTS.organizationMembershipUpdated, data: formatMembershipEvent(m) }),
      onDelete: (m) => eventBus.emit({ event: EVENTS.organizationMembershipDeleted, data: formatMembershipEvent(m) }),
    });
    // AuthKit groups. `group.created`/`updated`/`deleted` carry the full Group object the
    // spec's event data requires; `group.member_added`/`member_removed` carry only the two
    // ids, so the group's organization is recorded alongside for the events filter to scope
    // on. Hook-driven (not inline in the routes) so seeded groups fire the same events.
    ws.groups.setHooks({
      onInsert: (g) => eventBus.emit({ event: EVENTS.groupCreated, data: formatGroup(g) }),
      onUpdate: (g) => eventBus.emit({ event: EVENTS.groupUpdated, data: formatGroup(g) }),
      onDelete: (g) => eventBus.emit({ event: EVENTS.groupDeleted, data: formatGroup(g) }),
    });
    ws.groupMemberships.setHooks({
      onInsert: (gm) =>
        eventBus.emit({
          event: EVENTS.groupMemberAdded,
          data: { group_id: gm.group_id, organization_membership_id: gm.organization_membership_id },
          organization_id: ws.groups.get(gm.group_id)?.organization_id ?? null,
        }),
      onDelete: (gm) =>
        eventBus.emit({
          event: EVENTS.groupMemberRemoved,
          data: { group_id: gm.group_id, organization_membership_id: gm.organization_membership_id },
          organization_id: ws.groups.get(gm.group_id)?.organization_id ?? null,
        }),
    });
    // Pipes connected accounts. The event is named by the state the row lands in, so the
    // pair cannot drift; deletion is the only way an account disconnects, so onDelete emits
    // the `disconnected` payload for a value no stored row ever holds. Hook-driven so seeded
    // accounts fire the same events.
    const connectedAccountEvent = (state: ConnectedAccountState) =>
      state === 'connected' ? EVENTS.pipesConnectedAccountConnected : EVENTS.pipesConnectedAccountReauthorizationNeeded;
    ws.connectedAccounts.setHooks({
      onInsert: (a) => eventBus.emit({ event: connectedAccountEvent(a.state), data: formatConnectedAccountEvent(a) }),
      onUpdate: (a, prev) => {
        if (a.state === prev.state) return;
        eventBus.emit({ event: connectedAccountEvent(a.state), data: formatConnectedAccountEvent(a) });
      },
      onDelete: (a) =>
        eventBus.emit({
          event: EVENTS.pipesConnectedAccountDisconnected,
          data: formatConnectedAccountEvent(a, 'disconnected'),
        }),
    });
    ws.connections.setHooks({
      // The spec has no connection.created/updated — only activation state transitions
      onInsert: (c) => {
        if (c.state === 'active') eventBus.emit({ event: EVENTS.connectionActivated, data: formatConnection(c) });
      },
      onUpdate: (c, prev) => {
        if (c.state === prev.state) return;
        if (c.state === 'active') {
          eventBus.emit({ event: EVENTS.connectionActivated, data: formatConnection(c) });
        } else if (c.state === 'inactive') {
          eventBus.emit({ event: EVENTS.connectionDeactivated, data: formatConnection(c) });
        }
      },
      onDelete: (c) => eventBus.emit({ event: EVENTS.connectionDeleted, data: formatConnection(c) }),
    });
    ws.sessions.setHooks({
      onInsert: (s) => eventBus.emit({ event: EVENTS.sessionCreated, data: formatSession(s) }),
      onDelete: (s) => {
        eventBus.emit({ event: EVENTS.sessionRevoked, data: formatSession(s) });
        revokeAgentSessionsForUserSession(ws, s.id);
      },
    });
    ws.invitations.setHooks({
      onInsert: (i) => eventBus.emit({ event: EVENTS.invitationCreated, data: formatInvitation(i) }),
    });
    // Lifecycle resources created during login flows. No delete hooks: codes are
    // deleted when consumed, and the spec has no events for that.
    ws.emailVerifications.setHooks({
      onInsert: (ev) => eventBus.emit({ event: EVENTS.emailVerificationCreated, data: formatEmailVerification(ev) }),
    });
    ws.magicAuths.setHooks({
      onInsert: (ma) => eventBus.emit({ event: EVENTS.magicAuthCreated, data: formatMagicAuth(ma) }),
    });
    ws.passwordResets.setHooks({
      onInsert: (pr) => eventBus.emit({ event: EVENTS.passwordResetCreated, data: formatPasswordReset(pr) }),
    });
    // Organization-scoped roles share the roles collection but have their own spec events
    ws.roles.setHooks({
      onInsert: (r) =>
        eventBus.emit({
          event: r.type === 'OrganizationRole' ? EVENTS.organizationRoleCreated : EVENTS.roleCreated,
          data: formatRole(r, ws),
        }),
      onUpdate: (r) =>
        eventBus.emit({
          event: r.type === 'OrganizationRole' ? EVENTS.organizationRoleUpdated : EVENTS.roleUpdated,
          data: formatRole(r, ws),
        }),
      onDelete: (r) => {
        // The role routes delete the role row before cascading its joins, so the
        // permissions are still resolvable here. Production's organization_role.deleted
        // carries them; its role.deleted never does.
        const data = formatRole(r, ws);
        if (r.type === 'OrganizationRole') {
          eventBus.emit({ event: EVENTS.organizationRoleDeleted, data });
        } else {
          delete data.permissions;
          eventBus.emit({ event: EVENTS.roleDeleted, data });
        }
      },
    });
    ws.permissions.setHooks({
      onInsert: (p) => eventBus.emit({ event: EVENTS.permissionCreated, data: formatPermission(p) }),
      onUpdate: (p) => eventBus.emit({ event: EVENTS.permissionUpdated, data: formatPermission(p) }),
      onDelete: (p) => eventBus.emit({ event: EVENTS.permissionDeleted, data: formatPermission(p) }),
    });
    ws.directories.setHooks({
      // The spec has no dsync.updated — only activation and deletion. Activation is what
      // `linked` means: a directory seeded `unlinked` or `invalid_credentials` has not
      // activated, the same way an inactive connection does not announce itself.
      onInsert: (d) => {
        if (d.state === 'linked') eventBus.emit({ event: EVENTS.dsyncActivated, data: formatDirectory(d) });
      },
      onDelete: (d) => eventBus.emit({ event: EVENTS.dsyncDeleted, data: formatDirectory(d) }),
    });
    const emitDirectoryGroupMembership = (user: WorkOSDirectoryUser, groupId: string, added: boolean) => {
      const group = ws.directoryGroups.get(groupId);
      eventBus.emit({
        event: added ? EVENTS.dsyncGroupUserAdded : EVENTS.dsyncGroupUserRemoved,
        data: {
          directory_id: user.directory_id,
          user: formatDirectoryUser(user),
          group: group ? formatDirectoryGroup(group) : { object: 'directory_group', id: groupId },
        },
        organization_id: user.organization_id,
      });
    };
    ws.directoryUsers.setHooks({
      onInsert: (u) => {
        eventBus.emit({ event: EVENTS.dsyncUserCreated, data: formatDirectoryUser(u) });
        for (const group of u.groups) emitDirectoryGroupMembership(u, group.id, true);
      },
      onUpdate: (u, previous) => {
        eventBus.emit({ event: EVENTS.dsyncUserUpdated, data: formatDirectoryUser(u) });
        const before = new Set(previous.groups.map((group) => group.id));
        const after = new Set(u.groups.map((group) => group.id));
        for (const groupId of after) if (!before.has(groupId)) emitDirectoryGroupMembership(u, groupId, true);
        for (const groupId of before) if (!after.has(groupId)) emitDirectoryGroupMembership(u, groupId, false);
      },
      onDelete: (u) => {
        for (const group of u.groups) emitDirectoryGroupMembership(u, group.id, false);
        eventBus.emit({ event: EVENTS.dsyncUserDeleted, data: formatDirectoryUser(u) });
      },
    });
    ws.directoryGroups.setHooks({
      onInsert: (g) => eventBus.emit({ event: EVENTS.dsyncGroupCreated, data: formatDirectoryGroup(g) }),
      onUpdate: (g) => eventBus.emit({ event: EVENTS.dsyncGroupUpdated, data: formatDirectoryGroup(g) }),
      onDelete: (g) => eventBus.emit({ event: EVENTS.dsyncGroupDeleted, data: formatDirectoryGroup(g) }),
    });
    ws.apiKeyRecords.setHooks({
      onInsert: (k) => eventBus.emit({ event: EVENTS.apiKeyCreated, data: formatApiKeyRecord(k) }),
      onUpdate: (k) => eventBus.emit({ event: EVENTS.apiKeyUpdated, data: formatApiKeyRecord(k) }),
      onDelete: (k) => eventBus.emit({ event: EVENTS.apiKeyRevoked, data: formatApiKeyRecord(k) }),
    });
    // Flag webhook payloads carry environment_id, which the REST Flag object does not. Flags
    // are not environment-scoped in the store, so every flag event reports the same default
    // environment — including flag.rule_updated, emitted from the target routes.
    //
    // The context here is the base envelope only: access_type and configured_targets are
    // defined on flag.rule_updated alone, so created/updated/deleted must not carry them.
    const flagEvent = (event: string) => (f: Parameters<typeof formatFeatureFlag>[0]) => {
      const environmentId = environmentIdFor();
      eventBus.emit({
        event,
        data: formatFeatureFlagEvent(f, environmentId),
        environment_id: environmentId,
        context: flagEventContext(),
      });
    };
    ws.featureFlags.setHooks({
      onInsert: flagEvent(EVENTS.flagCreated),
      onUpdate: flagEvent(EVENTS.flagUpdated),
      onDelete: flagEvent(EVENTS.flagDeleted),
    });
    ws.agentBlueprints.setHooks({
      onInsert: (b) => eventBus.emit({ event: EVENTS.agentBlueprintCreated, data: formatAgentBlueprint(b) }),
      onUpdate: (b) => eventBus.emit({ event: EVENTS.agentBlueprintUpdated, data: formatAgentBlueprint(b) }),
      onDelete: (b) => eventBus.emit({ event: EVENTS.agentBlueprintDeleted, data: formatAgentBlueprint(b) }),
    });
    ws.agentInstances.setHooks({
      onInsert: (i) => eventBus.emit({ event: EVENTS.agentInstanceCreated, data: formatAgentInstance(i) }),
      onDelete: (i) => eventBus.emit({ event: EVENTS.agentInstanceDeleted, data: formatAgentInstance(i) }),
    });
    // Session payloads need the owning instance's organization_id. Refresh rotation goes
    // through updateSilent, so the only update that reaches this hook is a revocation; the
    // spec has no session.deleted event, and teardown revokes live sessions before deleting.
    ws.agentInstanceSessions.setHooks({
      onInsert: (s) => {
        const instance = ws.agentInstances.get(s.agent_instance_id);
        if (!instance) return;
        eventBus.emit({
          event: EVENTS.agentInstanceSessionCreated,
          data: formatAgentInstanceSessionEvent(s, instance.organization_id, { permissionSlugs: s.permissions }),
        });
      },
      onUpdate: (s, prev) => {
        if (s.revoked_at === null || prev.revoked_at !== null) return;
        const instance = ws.agentInstances.get(s.agent_instance_id);
        if (!instance) return;
        eventBus.emit({
          event: EVENTS.agentInstanceSessionRevoked,
          data: formatAgentInstanceSessionEvent(s, instance.organization_id),
        });
      },
    });
    ws.webhookEndpoints.setHooks({
      onInsert: () => eventBus.rebuildIndex(),
      onUpdate: () => eventBus.rebuildIndex(),
      onDelete: () => eventBus.rebuildIndex(),
    });
  },
  seed(_store: Store, _baseUrl: string): void {
    // No default seed data — users provide their own via seedFromConfig
  },
};

export default workosPlugin;
