/**
 * Configuration validation for seed config files
 */
import type { WorkOSSeedConfig } from './index.js';
import { validateJwtTemplateContent } from './jwt-template.js';
import { isValidResourceTypeSlug } from './constants.js';
import { AGENT_SESSION_SETTING_LIMITS } from './agent-sessions.js';
import { normalizeEmail, type NormalizedEmail } from './helpers.js';

/**
 * A seed is the one creation path that does not go through a route, so it is held to what the
 * routes enforce: an address is trimmed and is shaped like an address. Anything looser and a seed
 * is the remaining way to write a user under a spelling no lookup by email resolves — which is the
 * state all of this exists to prevent.
 *
 * Returns the stored form, or the problem for the caller to word in its own terms: each site
 * already says something more specific than "email" about what the address is for.
 */
function seedEmail(value: unknown): NormalizedEmail {
  return normalizeEmail(value, { requireShape: true });
}

/**
 * A pinned id is addressed as a single path segment (`/organizations/:id`,
 * `/user_management/users/:id`), so it must be URL-safe — a delimiter like `/` would
 * make the seeded resource unreachable by its documented id route. This charset accepts
 * every real WorkOS id (`org_01…`, `user_01…`) and every emulator-generated id
 * (`prefix_<Crockford-Base32>`) while rejecting anything that would split or need encoding.
 */
const PINNED_ID_PATTERN = /^[A-Za-z0-9_-]+$/;

export interface ConfigValidationError {
  path: string;
  message: string;
  value?: unknown;
}

export interface ConfigValidationResult {
  valid: boolean;
  errors: ConfigValidationError[];
}

export function validateSeedConfig(config: WorkOSSeedConfig): ConfigValidationResult {
  const errors: ConfigValidationError[] = [];

  // Seeded user ids are generated at insert time, so org memberships reference users
  // by email — collect the emails defined in this config for cross-referencing. Normalized the way
  // the store resolves them: lowercased, because every lookup by email is case-insensitive, and
  // trimmed, because that is the form seeding writes. A membership for 'a@x.test' names the user
  // seeded as ' A@x.test ', and resolving it any other way would reject a reference the running
  // emulator then honours.
  const userEmails = new Set(
    Array.isArray(config.users)
      ? config.users
          .map((u) => seedEmail(u.email))
          .filter((r): r is { ok: true; email: string } => r.ok)
          .map((r) => r.email.toLowerCase())
      : [],
  );

  // Validate users
  if (config.users) {
    if (!Array.isArray(config.users)) {
      errors.push({
        path: 'users',
        message: 'users must be an array',
        value: config.users,
      });
    } else {
      config.users.forEach((user, index) => {
        const email = seedEmail(user.email);
        if (!email.ok) {
          errors.push({
            path: `users[${index}].email`,
            message:
              email.problem === 'malformed'
                ? // Same standard as the two routes that create users: an address that could only
                  // be a typo becomes an account nothing can reach, and a seed is the one creation
                  // path with no route in front of it to say so.
                  'email must be a valid email address'
                : 'email is required and must be a string',
            value: user.email,
          });
        }
        if (user.id !== undefined && (typeof user.id !== 'string' || !PINNED_ID_PATTERN.test(user.id))) {
          errors.push({
            path: `users[${index}].id`,
            message: 'id must be a non-empty, URL-safe string (letters, digits, "_" or "-") if provided',
            value: user.id,
          });
        }
        if (user.password && typeof user.password !== 'string') {
          errors.push({
            path: `users[${index}].password`,
            message: 'password must be a string if provided',
            value: user.password,
          });
        }
        if (user.email_verified !== undefined && typeof user.email_verified !== 'boolean') {
          errors.push({
            path: `users[${index}].email_verified`,
            message: 'email_verified must be a boolean if provided',
            value: user.email_verified,
          });
        }
        // Both are serialized straight onto the identity the users endpoint returns and the
        // `user.identities` map a template reads, so a non-string here is a contract the emulator
        // would break on behalf of a config only YAML or JSON could have written. The provider is
        // not checked against the spec's enum — `connections[].connection_type` is not either, and
        // a list baked in here would reject a provider WorkOS adds later.
        if (user.oauth_provider !== undefined && (typeof user.oauth_provider !== 'string' || !user.oauth_provider)) {
          errors.push({
            path: `users[${index}].oauth_provider`,
            message: 'oauth_provider must be a non-empty string if provided',
            value: user.oauth_provider,
          });
        }
        if (user.oauth_idp_id !== undefined && (typeof user.oauth_idp_id !== 'string' || !user.oauth_idp_id)) {
          errors.push({
            path: `users[${index}].oauth_idp_id`,
            message: 'oauth_idp_id must be a non-empty string if provided',
            value: user.oauth_idp_id,
          });
        }
        // The YAML 1.2 parser the CLI uses reads `totp: yes` as the string "yes", not a boolean —
        // and `totp: no` as the equally truthy string "no", which the seed's truthiness check
        // would silently enroll a factor from, against what the config explicitly declined.
        if (user.totp !== undefined && typeof user.totp !== 'boolean') {
          errors.push({
            path: `users[${index}].totp`,
            message: 'totp must be a boolean if provided',
            value: user.totp,
          });
        }
      });

      // Email is the lookup key org memberships join on; duplicates would silently
      // bind a membership to the first match. Compared case-insensitively, matching the
      // uniqueness the API enforces: `POST /user_management/users` answers 409 for an address
      // differing only in case, so a seed that got two through would be the one way left to
      // manufacture the pair of accounts no lookup by email can tell apart.
      const seenEmails = new Set<string>();
      config.users.forEach((user, index) => {
        const email = seedEmail(user.email);
        if (!email.ok) return;
        const normalized = email.email.toLowerCase();
        if (seenEmails.has(normalized)) {
          errors.push({
            path: `users[${index}].email`,
            message: 'email must be unique across users',
            value: user.email,
          });
        }
        seenEmails.add(normalized);
      });

      // A pinned user id is the primary key in the store; two users sharing one would
      // silently overwrite each other on insert.
      const seenUserIds = new Set<string>();
      config.users.forEach((user, index) => {
        if (typeof user.id !== 'string' || user.id.length === 0) return;
        if (seenUserIds.has(user.id)) {
          errors.push({
            path: `users[${index}].id`,
            message: 'id must be unique across users',
            value: user.id,
          });
        }
        seenUserIds.add(user.id);
      });
    }
  }

  // Validate organizations
  if (config.organizations) {
    if (!Array.isArray(config.organizations)) {
      errors.push({
        path: 'organizations',
        message: 'organizations must be an array',
        value: config.organizations,
      });
    } else {
      config.organizations.forEach((org, index) => {
        if (!org.name || typeof org.name !== 'string') {
          errors.push({
            path: `organizations[${index}].name`,
            message: 'name is required and must be a string',
            value: org.name,
          });
        }
        if (org.id !== undefined && (typeof org.id !== 'string' || !PINNED_ID_PATTERN.test(org.id))) {
          errors.push({
            path: `organizations[${index}].id`,
            message: 'id must be a non-empty, URL-safe string (letters, digits, "_" or "-") if provided',
            value: org.id,
          });
        }
        if (
          org.entitlements !== undefined &&
          (!Array.isArray(org.entitlements) || org.entitlements.some((e) => typeof e !== 'string'))
        ) {
          errors.push({
            path: `organizations[${index}].entitlements`,
            message: 'entitlements must be an array of strings if provided',
            value: org.entitlements,
          });
        }
        if (org.domains) {
          if (!Array.isArray(org.domains)) {
            errors.push({
              path: `organizations[${index}].domains`,
              message: 'domains must be an array if provided',
              value: org.domains,
            });
          } else {
            org.domains.forEach((domain, dIndex) => {
              if (!domain.domain || typeof domain.domain !== 'string') {
                errors.push({
                  path: `organizations[${index}].domains[${dIndex}].domain`,
                  message: 'domain is required and must be a string',
                  value: domain.domain,
                });
              }
              if (domain.state && !['verified', 'pending'].includes(domain.state)) {
                errors.push({
                  path: `organizations[${index}].domains[${dIndex}].state`,
                  message: 'state must be "verified" or "pending" if provided',
                  value: domain.state,
                });
              }
            });
          }
        }
        if (org.memberships) {
          if (!Array.isArray(org.memberships)) {
            errors.push({
              path: `organizations[${index}].memberships`,
              message: 'memberships must be an array if provided',
              value: org.memberships,
            });
          } else {
            // `POST /user_management/organization_memberships` 409s a second non-inactive
            // membership for the same user, so seeding must not create one either: every
            // lookup that joins a user to their membership in an organization reads the
            // first match and would otherwise leave the second stale. Repeated `inactive`
            // entries are legal — deactivating and re-adding leaves exactly that trail.
            const liveMemberEmails = new Set<string>();
            org.memberships.forEach((membership, mIndex) => {
              // The pre-rename key: it read as "pass a user_... id", which can never
              // resolve (ids are generated at startup) — point at `email` instead.
              const legacyUserId = (membership as { user_id?: unknown }).user_id;
              const memberEmail = seedEmail(membership.email);
              if (!memberEmail.ok) {
                if (legacyUserId !== undefined) {
                  errors.push({
                    path: `organizations[${index}].memberships[${mIndex}].user_id`,
                    message:
                      'memberships reference seeded users by email — use `email` (seeded user ids are generated at startup, so a user_id literal can never resolve)',
                    value: legacyUserId,
                  });
                } else {
                  errors.push({
                    path: `organizations[${index}].memberships[${mIndex}].email`,
                    message:
                      memberEmail.problem === 'malformed'
                        ? 'email must be a valid email address'
                        : 'email is required and must be the email of a user defined in users',
                    value: membership.email,
                  });
                }
              } else if (!userEmails.has(memberEmail.email.toLowerCase())) {
                // A dangling reference would seed a membership whose embedded user
                // cannot resolve, which membership serialization rejects.
                errors.push({
                  path: `organizations[${index}].memberships[${mIndex}].email`,
                  message: 'email must match a user defined in users',
                  value: membership.email,
                });
              }
              if (membership.status && !['active', 'inactive', 'pending'].includes(membership.status)) {
                errors.push({
                  path: `organizations[${index}].memberships[${mIndex}].status`,
                  message: 'status must be "active", "inactive", or "pending" if provided',
                  value: membership.status,
                });
              }
              if (memberEmail.ok && membership.status !== 'inactive') {
                const key = memberEmail.email.toLowerCase();
                if (liveMemberEmails.has(key)) {
                  errors.push({
                    path: `organizations[${index}].memberships[${mIndex}].email`,
                    message: `duplicate membership for '${membership.email}' — an organization holds at most one membership per user that is not inactive`,
                    value: membership.email,
                  });
                }
                liveMemberEmails.add(key);
              }
            });
          }
        }
        if (org.groups) {
          if (!Array.isArray(org.groups)) {
            errors.push({
              path: `organizations[${index}].groups`,
              message: 'groups must be an array if provided',
              value: org.groups,
            });
          } else {
            // Group members reference an org membership by the user's email, and that
            // membership must be one declared in this org's `memberships` — the only seed
            // path that creates org memberships. Collect those emails to cross-reference,
            // the way `userEmails` cross-references membership emails against users.
            // Guard against a truthy non-array `memberships`: the memberships block above
            // already recorded a structured error for that, and falling through to here
            // would call `.map()` on the invalid value and crash startup instead of
            // returning that error.
            const orgMembershipEmails = new Set(
              (Array.isArray(org.memberships) ? org.memberships : [])
                .map((m) => seedEmail(m.email))
                .filter((r): r is { ok: true; email: string } => r.ok)
                .map((r) => r.email.toLowerCase()),
            );
            org.groups.forEach((group, gIndex) => {
              // A non-object entry (e.g. `groups: [null]` from a YAML/JSON typo) would
              // throw on `group.name` below; record a structured error and skip the
              // property checks rather than crashing startup or `--validate-config`.
              if (group === null || typeof group !== 'object') {
                errors.push({
                  path: `organizations[${index}].groups[${gIndex}]`,
                  message: 'each group must be an object',
                  value: group,
                });
                return;
              }
              if (!group.name || typeof group.name !== 'string') {
                errors.push({
                  path: `organizations[${index}].groups[${gIndex}].name`,
                  message: 'name is required and must be a string',
                  value: group.name,
                });
              }
              if (
                group.description !== undefined &&
                group.description !== null &&
                typeof group.description !== 'string'
              ) {
                errors.push({
                  path: `organizations[${index}].groups[${gIndex}].description`,
                  message: 'description must be a string or null if provided',
                  value: group.description,
                });
              }
              if (group.members) {
                if (!Array.isArray(group.members)) {
                  errors.push({
                    path: `organizations[${index}].groups[${gIndex}].members`,
                    message: 'members must be an array of emails if provided',
                    value: group.members,
                  });
                } else {
                  group.members.forEach((email, mIndex) => {
                    const memberEmail = seedEmail(email);
                    if (!memberEmail.ok) {
                      errors.push({
                        path: `organizations[${index}].groups[${gIndex}].members[${mIndex}]`,
                        message:
                          memberEmail.problem === 'malformed'
                            ? 'must be a valid email address'
                            : 'each member must be the email of a user',
                        value: email,
                      });
                    } else if (!orgMembershipEmails.has(memberEmail.email.toLowerCase())) {
                      errors.push({
                        path: `organizations[${index}].groups[${gIndex}].members[${mIndex}]`,
                        message: "member email must match a membership defined in this organization's `memberships`",
                        value: email,
                      });
                    }
                  });
                }
              }
            });
          }
        }
      });

      // Organization name is the lookup key for connections, connectApplications, and
      // apiKeys seeds; duplicates would silently bind those to the first match.
      const seenOrgNames = new Set<string>();
      config.organizations.forEach((org, index) => {
        if (!org.name || typeof org.name !== 'string') return;
        if (seenOrgNames.has(org.name)) {
          errors.push({
            path: `organizations[${index}].name`,
            message: 'name must be unique across organizations',
            value: org.name,
          });
        }
        seenOrgNames.add(org.name);
      });

      // A pinned organization id is the primary key in the store; two orgs sharing one
      // would silently overwrite each other on insert.
      const seenOrgIds = new Set<string>();
      config.organizations.forEach((org, index) => {
        if (typeof org.id !== 'string' || org.id.length === 0) return;
        if (seenOrgIds.has(org.id)) {
          errors.push({
            path: `organizations[${index}].id`,
            message: 'id must be unique across organizations',
            value: org.id,
          });
        }
        seenOrgIds.add(org.id);
      });
    }
  }

  // Validate connections
  if (config.connections) {
    if (!Array.isArray(config.connections)) {
      errors.push({
        path: 'connections',
        message: 'connections must be an array',
        value: config.connections,
      });
    } else {
      config.connections.forEach((conn, index) => {
        if (!conn.name || typeof conn.name !== 'string') {
          errors.push({
            path: `connections[${index}].name`,
            message: 'name is required and must be a string',
            value: conn.name,
          });
        }
        if (!conn.organization || typeof conn.organization !== 'string') {
          errors.push({
            path: `connections[${index}].organization`,
            message: 'organization is required and must be a string',
            value: conn.organization,
          });
        }
        if (conn.state && !['active', 'inactive', 'validating'].includes(conn.state)) {
          errors.push({
            path: `connections[${index}].state`,
            message: 'state must be "active", "inactive", or "validating" if provided',
            value: conn.state,
          });
        }
      });
    }
  }

  // Validate directories
  if (config.directories) {
    if (!Array.isArray(config.directories)) {
      errors.push({
        path: 'directories',
        message: 'directories must be an array',
        value: config.directories,
      });
    } else {
      config.directories.forEach((dir, index) => {
        // A non-object entry (e.g. `directories: [null]` from a YAML typo) would throw on
        // the property reads below; record a structured error instead of crashing startup.
        if (dir === null || typeof dir !== 'object') {
          errors.push({
            path: `directories[${index}]`,
            message: 'each directory must be an object',
            value: dir,
          });
          return;
        }
        if (!dir.name || typeof dir.name !== 'string') {
          errors.push({
            path: `directories[${index}].name`,
            message: 'name is required and must be a string',
            value: dir.name,
          });
        }
        if (!dir.organization || typeof dir.organization !== 'string') {
          errors.push({
            path: `directories[${index}].organization`,
            message: 'organization is required and must be a string',
            value: dir.organization,
          });
        } else if (
          !(Array.isArray(config.organizations) ? config.organizations : []).some(
            (org) => org !== null && typeof org === 'object' && org.name === dir.organization,
          )
        ) {
          // seedFromConfig skips a directory whose organization does not resolve, so without
          // this a typo silently produces no directory at all.
          errors.push({
            path: `directories[${index}].organization`,
            message: `organization '${dir.organization}' is not declared in organizations`,
            value: dir.organization,
          });
        }
        if (dir.state && !['linked', 'unlinked', 'invalid_credentials'].includes(dir.state)) {
          errors.push({
            path: `directories[${index}].state`,
            message: 'state must be "linked", "unlinked", or "invalid_credentials" if provided',
            value: dir.state,
          });
        }
        // Only the type is checked: the seed path stores these verbatim, so a YAML
        // `domain: 123` would otherwise reach `GET /directories` as a number. Null is
        // accepted as absent, the way `?? null` reads it there.
        for (const field of ['type', 'domain', 'external_key'] as const) {
          if (dir[field] != null && typeof dir[field] !== 'string') {
            errors.push({
              path: `directories[${index}].${field}`,
              message: `${field} must be a string if provided`,
              value: dir[field],
            });
          }
        }

        const groupNames = new Set<string>();
        if (dir.groups !== undefined && !Array.isArray(dir.groups)) {
          errors.push({
            path: `directories[${index}].groups`,
            message: 'groups must be an array of names or { name, role } objects',
            value: dir.groups,
          });
        } else {
          dir.groups?.forEach((entry, groupIndex) => {
            const groupName = typeof entry === 'string' ? entry : entry?.name;
            if (entry === null || (typeof entry !== 'string' && typeof entry !== 'object')) {
              errors.push({
                path: `directories[${index}].groups[${groupIndex}]`,
                message: 'each group must be a name or an object with a name',
                value: entry,
              });
              return;
            }
            if (typeof groupName !== 'string' || !groupName) {
              errors.push({
                path: `directories[${index}].groups[${groupIndex}].name`,
                message: 'name is required and must be a non-empty string',
                value: groupName,
              });
              return;
            }
            if (typeof entry === 'object' && entry.role !== undefined && typeof entry.role !== 'string') {
              errors.push({
                path: `directories[${index}].groups[${groupIndex}].role`,
                message: 'role must be a string if provided',
                value: entry.role,
              });
            }
            if (groupNames.has(groupName)) {
              errors.push({
                path: `directories[${index}].groups`,
                message: `duplicate group name '${groupName}'`,
                value: groupName,
              });
            }
            groupNames.add(groupName);
          });
        }

        if (dir.users !== undefined && !Array.isArray(dir.users)) {
          errors.push({
            path: `directories[${index}].users`,
            message: 'users must be an array',
            value: dir.users,
          });
          return;
        }
        const userEmails = new Set<string>();
        dir.users?.forEach((user, userIndex) => {
          if (user === null || typeof user !== 'object') {
            errors.push({
              path: `directories[${index}].users[${userIndex}]`,
              message: 'each directory user must be an object',
              value: user,
            });
            return;
          }
          const email = seedEmail(user.email);
          if (!email.ok) {
            errors.push({
              path: `directories[${index}].users[${userIndex}].email`,
              message:
                email.problem === 'malformed'
                  ? 'email must be a valid email address'
                  : 'email is required and must be a string',
              value: user.email,
            });
          } else if (userEmails.has(email.email.toLowerCase())) {
            errors.push({
              path: `directories[${index}].users[${userIndex}].email`,
              message: `duplicate directory user '${user.email}'`,
              value: user.email,
            });
          } else {
            userEmails.add(email.email.toLowerCase());
          }
          if (user.state && !['active', 'inactive'].includes(user.state)) {
            errors.push({
              path: `directories[${index}].users[${userIndex}].state`,
              message: 'state must be "active" or "inactive" if provided',
              value: user.state,
            });
          }
          for (const field of ['first_name', 'last_name', 'username', 'idp_id', 'role'] as const) {
            if (user[field] != null && typeof user[field] !== 'string') {
              errors.push({
                path: `directories[${index}].users[${userIndex}].${field}`,
                message: `${field} must be a string if provided`,
                value: user[field],
              });
            }
          }
          if (
            user.custom_attributes != null &&
            (typeof user.custom_attributes !== 'object' || Array.isArray(user.custom_attributes))
          ) {
            errors.push({
              path: `directories[${index}].users[${userIndex}].custom_attributes`,
              message: 'custom_attributes must be an object if provided',
              value: user.custom_attributes,
            });
          }
          if (user.groups !== undefined && !Array.isArray(user.groups)) {
            errors.push({
              path: `directories[${index}].users[${userIndex}].groups`,
              message: 'groups must be an array of strings',
              value: user.groups,
            });
            return;
          }
          // A user's group names are resolved to generated ids at seed time, so an unknown
          // name would throw there. Reject it here, where the error names the config path.
          user.groups?.forEach((groupName, gIndex) => {
            if (typeof groupName !== 'string') {
              errors.push({
                path: `directories[${index}].users[${userIndex}].groups[${gIndex}]`,
                message: 'each group must be a name',
                value: groupName,
              });
              return;
            }
            if (!groupNames.has(groupName)) {
              errors.push({
                path: `directories[${index}].users[${userIndex}].groups`,
                message: `group '${groupName}' is not declared in directories[${index}].groups`,
                value: groupName,
              });
            }
          });
        });
      });
    }
  }

  // Validate connected accounts
  if (config.connectedAccounts) {
    if (!Array.isArray(config.connectedAccounts)) {
      errors.push({
        path: 'connectedAccounts',
        message: 'connectedAccounts must be an array',
        value: config.connectedAccounts,
      });
    } else {
      // Organization name is the join key, the same one connections use.
      const orgNames = new Set(
        Array.isArray(config.organizations)
          ? config.organizations.map((o) => o.name).filter((n): n is string => typeof n === 'string')
          : [],
      );
      // (user, provider, organization) is the key requests address; a duplicate would seed
      // the pair POST answers 409 for, and every lookup would only ever resolve the first.
      const seenAccounts = new Set<string>();
      config.connectedAccounts.forEach((account, index) => {
        // A non-object entry (e.g. `connectedAccounts: [null]` from a YAML typo) would throw
        // on the property reads below; record a structured error instead of crashing startup.
        if (account === null || typeof account !== 'object') {
          errors.push({
            path: `connectedAccounts[${index}]`,
            message: 'each connected account must be an object',
            value: account,
          });
          return;
        }
        const email = seedEmail(account.email);
        if (!email.ok) {
          errors.push({
            path: `connectedAccounts[${index}].email`,
            message:
              email.problem === 'malformed'
                ? 'email must be a valid email address'
                : 'email is required and must be the email of a user defined in users',
            value: account.email,
          });
        } else if (!userEmails.has(email.email.toLowerCase())) {
          errors.push({
            path: `connectedAccounts[${index}].email`,
            message: 'email must match a user defined in users',
            value: account.email,
          });
        }
        if (!account.provider || typeof account.provider !== 'string') {
          errors.push({
            path: `connectedAccounts[${index}].provider`,
            message: 'provider is required and must be a non-empty string (the slug requests address, e.g. "github")',
            value: account.provider,
          });
        }
        if (
          account.organization !== undefined &&
          (typeof account.organization !== 'string' || !orgNames.has(account.organization))
        ) {
          errors.push({
            path: `connectedAccounts[${index}].organization`,
            message: 'organization must name an organization defined in organizations',
            value: account.organization,
          });
        }
        if (
          account.scopes !== undefined &&
          (!Array.isArray(account.scopes) || account.scopes.some((s) => typeof s !== 'string'))
        ) {
          errors.push({
            path: `connectedAccounts[${index}].scopes`,
            message: 'scopes must be an array of strings if provided',
            value: account.scopes,
          });
        }
        if (account.state && !['connected', 'needs_reauthorization'].includes(account.state)) {
          errors.push({
            path: `connectedAccounts[${index}].state`,
            message:
              'state must be "connected" or "needs_reauthorization" if provided — a disconnected account is a deleted one, so it cannot be seeded',
            value: account.state,
          });
        }
        if (email.ok && typeof account.provider === 'string' && account.provider) {
          const key = [
            email.email.toLowerCase(),
            account.provider,
            typeof account.organization === 'string' ? account.organization : '',
          ].join('\u0000');
          if (seenAccounts.has(key)) {
            errors.push({
              path: `connectedAccounts[${index}]`,
              message: 'duplicate connected account for this user, provider, and organization',
              value: { email: account.email, provider: account.provider, organization: account.organization },
            });
          }
          seenAccounts.add(key);
        }
      });
    }
  }

  // Validate roles
  if (config.roles) {
    if (!Array.isArray(config.roles)) {
      errors.push({
        path: 'roles',
        message: 'roles must be an array',
        value: config.roles,
      });
    } else {
      config.roles.forEach((role, index) => {
        if (!role.slug || typeof role.slug !== 'string') {
          errors.push({
            path: `roles[${index}].slug`,
            message: 'slug is required and must be a string',
            value: role.slug,
          });
        }
        if (!role.name || typeof role.name !== 'string') {
          errors.push({
            path: `roles[${index}].name`,
            message: 'name is required and must be a string',
            value: role.name,
          });
        }
        if (role.type && !['EnvironmentRole', 'OrganizationRole'].includes(role.type)) {
          errors.push({
            path: `roles[${index}].type`,
            message: 'type must be "EnvironmentRole" or "OrganizationRole" if provided',
            value: role.type,
          });
        }
        if (!isValidResourceTypeSlug(role.resource_type_slug)) {
          errors.push({
            path: `roles[${index}].resource_type_slug`,
            message: 'resource_type_slug must be a non-empty string if provided',
            value: role.resource_type_slug,
          });
        }
      });
    }
  }

  // Validate permissions
  if (config.permissions) {
    if (!Array.isArray(config.permissions)) {
      errors.push({
        path: 'permissions',
        message: 'permissions must be an array',
        value: config.permissions,
      });
    } else {
      config.permissions.forEach((perm, index) => {
        if (!perm.slug || typeof perm.slug !== 'string') {
          errors.push({
            path: `permissions[${index}].slug`,
            message: 'slug is required and must be a string',
            value: perm.slug,
          });
        }
        if (!perm.name || typeof perm.name !== 'string') {
          errors.push({
            path: `permissions[${index}].name`,
            message: 'name is required and must be a string',
            value: perm.name,
          });
        }
        if (!isValidResourceTypeSlug(perm.resource_type_slug)) {
          errors.push({
            path: `permissions[${index}].resource_type_slug`,
            message: 'resource_type_slug must be a non-empty string if provided',
            value: perm.resource_type_slug,
          });
        }
      });
    }
  }

  // Validate webhook endpoints
  if (config.webhookEndpoints) {
    if (!Array.isArray(config.webhookEndpoints)) {
      errors.push({
        path: 'webhookEndpoints',
        message: 'webhookEndpoints must be an array',
        value: config.webhookEndpoints,
      });
    } else {
      config.webhookEndpoints.forEach((endpoint, index) => {
        const url = endpoint.endpoint_url || endpoint.url;
        if (!url || typeof url !== 'string') {
          errors.push({
            path: `webhookEndpoints[${index}].endpoint_url`,
            message: 'endpoint_url is required and must be a string',
            value: url,
          });
        } else {
          try {
            new URL(url);
          } catch {
            errors.push({
              path: `webhookEndpoints[${index}].endpoint_url`,
              message: 'endpoint_url must be a valid URL',
              value: url,
            });
          }
        }
        if (endpoint.events && !Array.isArray(endpoint.events)) {
          errors.push({
            path: `webhookEndpoints[${index}].events`,
            message: 'events must be an array if provided',
            value: endpoint.events,
          });
        }
        // The secret keys every signature the endpoint will ever receive; a non-string here
        // (only YAML or JSON could write one) would sign deliveries with a coerced value no
        // consumer's verifier was configured with.
        if (endpoint.secret !== undefined && (typeof endpoint.secret !== 'string' || !endpoint.secret)) {
          errors.push({
            path: `webhookEndpoints[${index}].secret`,
            message: 'secret must be a non-empty string if provided',
            value: endpoint.secret,
          });
        }
      });
    }
  }

  // Validate invitations
  if (config.invitations) {
    if (!Array.isArray(config.invitations)) {
      errors.push({
        path: 'invitations',
        message: 'invitations must be an array',
        value: config.invitations,
      });
    } else {
      config.invitations.forEach((inv, index) => {
        const email = seedEmail(inv.email);
        if (!email.ok) {
          errors.push({
            path: `invitations[${index}].email`,
            message:
              email.problem === 'malformed'
                ? // As POST /user_management/invitations now answers: acceptance resolves the
                  // recipient by this address, so a typo is an invitation that enrolls nobody.
                  'email must be a valid email address'
                : 'email is required and must be a string',
            value: inv.email,
          });
        }
      });
    }
  }

  // Validate connect applications
  if (config.connectApplications) {
    if (!Array.isArray(config.connectApplications)) {
      errors.push({
        path: 'connectApplications',
        message: 'connectApplications must be an array',
        value: config.connectApplications,
      });
    } else {
      config.connectApplications.forEach((appConfig, index) => {
        if (!appConfig.name || typeof appConfig.name !== 'string') {
          errors.push({
            path: `connectApplications[${index}].name`,
            message: 'name is required and must be a string',
            value: appConfig.name,
          });
        }
        if (appConfig.type && !['m2m', 'oauth'].includes(appConfig.type)) {
          errors.push({
            path: `connectApplications[${index}].type`,
            message: 'type must be "m2m" or "oauth" if provided',
            value: appConfig.type,
          });
        }
        const type = appConfig.type ?? 'm2m';
        if (appConfig.is_first_party !== undefined && typeof appConfig.is_first_party !== 'boolean') {
          errors.push({
            path: `connectApplications[${index}].is_first_party`,
            message: 'is_first_party must be a boolean if provided',
            value: appConfig.is_first_party,
          });
        }
        if (appConfig.uses_pkce !== undefined && typeof appConfig.uses_pkce !== 'boolean') {
          errors.push({
            path: `connectApplications[${index}].uses_pkce`,
            message: 'uses_pkce must be a boolean if provided',
            value: appConfig.uses_pkce,
          });
        }
        // A third-party oauth application is reported with its owning organization, so it
        // needs one for the same reason an m2m application does.
        const needsOrganization = type === 'm2m' || appConfig.is_first_party === false;
        if (needsOrganization && (!appConfig.organization || typeof appConfig.organization !== 'string')) {
          errors.push({
            path: `connectApplications[${index}].organization`,
            message:
              type === 'm2m'
                ? 'organization is required for m2m applications'
                : 'organization is required when is_first_party is false',
            value: appConfig.organization,
          });
        }
        if (
          appConfig.scopes !== undefined &&
          (!Array.isArray(appConfig.scopes) || !appConfig.scopes.every((s) => typeof s === 'string'))
        ) {
          errors.push({
            path: `connectApplications[${index}].scopes`,
            message: 'scopes must be an array of strings if provided',
            value: appConfig.scopes,
          });
        }
        if (appConfig.audience !== undefined && typeof appConfig.audience !== 'string') {
          errors.push({
            path: `connectApplications[${index}].audience`,
            message: 'audience must be a string if provided',
            value: appConfig.audience,
          });
        }
        // Only the type is checked here: host policy lives in assertAllowedRedirectUri and
        // depends on runtime store state, so a non-string is refused at seed and a
        // disallowed host is reported by /oauth2/authorize.
        if (appConfig.login_url != null && typeof appConfig.login_url !== 'string') {
          errors.push({
            path: `connectApplications[${index}].login_url`,
            message: 'login_url must be a string if provided',
            value: appConfig.login_url,
          });
        }
      });

      // A client_id identifies exactly one application; duplicates make token exchange
      // ambiguous (the lookup would resolve only the first match), so reject them.
      const seenClientIds = new Set<string>();
      config.connectApplications.forEach((appConfig, index) => {
        if (!appConfig.client_id) return;
        if (seenClientIds.has(appConfig.client_id)) {
          errors.push({
            path: `connectApplications[${index}].client_id`,
            message: 'client_id must be unique across connectApplications',
            value: appConfig.client_id,
          });
        }
        seenClientIds.add(appConfig.client_id);
      });
    }
  }

  // Validate API key resources. The map form is the legacy auth allow-list and is
  // intentionally left unvalidated here; only the array (resource) form is checked.
  if (config.apiKeys && Array.isArray(config.apiKeys)) {
    config.apiKeys.forEach((keyConfig, index) => {
      if (!keyConfig.name || typeof keyConfig.name !== 'string') {
        errors.push({
          path: `apiKeys[${index}].name`,
          message: 'name is required and must be a string',
          value: keyConfig.name,
        });
      }
      if (!keyConfig.organization && !keyConfig.user_id) {
        errors.push({
          path: `apiKeys[${index}].organization`,
          message: 'organization or user_id is required',
        });
      }
      if (keyConfig.user_id && !keyConfig.organization) {
        errors.push({
          path: `apiKeys[${index}].organization`,
          message: 'organization is required when user_id is set (supplies organization_id)',
        });
      }
      if (
        keyConfig.value !== undefined &&
        (typeof keyConfig.value !== 'string' || !keyConfig.value.startsWith('sk_'))
      ) {
        errors.push({
          path: `apiKeys[${index}].value`,
          message: 'value must be a string starting with "sk_" if provided',
          value: keyConfig.value,
        });
      }
      if (keyConfig.permissions && !Array.isArray(keyConfig.permissions)) {
        errors.push({
          path: `apiKeys[${index}].permissions`,
          message: 'permissions must be an array if provided',
          value: keyConfig.permissions,
        });
      }
    });

    // A key value is the identity of the secret: it is the auth allow-list's map key and
    // the lookup key for the resource behind it. Two entries sharing one would split that
    // identity — the allow-list keeps the last entry's environment and expiry while the
    // record lookup resolves the first, so validation would gate on one seed entry and
    // report another's owner and permissions. Deleting either would also stop the other
    // authenticating. Production cannot issue one secret twice, so reject it here rather
    // than pick a winner.
    const seenKeyValues = new Set<string>();
    config.apiKeys.forEach((keyConfig, index) => {
      if (typeof keyConfig.value !== 'string' || keyConfig.value.length === 0) return;
      if (seenKeyValues.has(keyConfig.value)) {
        errors.push({
          path: `apiKeys[${index}].value`,
          message: 'value must be unique across apiKeys',
          value: keyConfig.value,
        });
      }
      seenKeyValues.add(keyConfig.value);
    });
  }

  // Validate feature flags. Seeding is the only way a flag exists at all — production has no
  // create-flag endpoint — so an unresolvable target here is a flag that silently reaches
  // nobody, which is exactly the bug a test suite would blame on its own code.
  if (config.featureFlags) {
    if (!Array.isArray(config.featureFlags)) {
      errors.push({
        path: 'featureFlags',
        message: 'featureFlags must be an array',
        value: config.featureFlags,
      });
    } else {
      const orgNames = new Set(
        Array.isArray(config.organizations)
          ? config.organizations.map((o) => o.name).filter((n): n is string => typeof n === 'string')
          : [],
      );
      const seenSlugs = new Set<string>();
      // A pinned flag id is the primary key in the store; two flags sharing one would silently
      // overwrite each other on insert while both slugs stay in the slug index, so a lookup by
      // the losing slug would resolve to the surviving flag's values.
      const seenFlagIds = new Set<string>();

      config.featureFlags.forEach((flag, index) => {
        const at = (field: string) => `featureFlags[${index}].${field}`;

        // A YAML list item left empty parses as null, which every field check below would
        // dereference. Reported as a validation error so `--validate-config` stays useful.
        if (flag === null || typeof flag !== 'object' || Array.isArray(flag)) {
          errors.push({ path: `featureFlags[${index}]`, message: 'each feature flag must be an object', value: flag });
          return;
        }

        if (flag.id !== undefined) {
          if (typeof flag.id !== 'string' || !PINNED_ID_PATTERN.test(flag.id)) {
            errors.push({
              path: at('id'),
              message: 'id must be a string of letters, numbers, hyphens or underscores if provided',
              value: flag.id,
            });
          } else if (seenFlagIds.has(flag.id)) {
            errors.push({ path: at('id'), message: 'id must be unique across featureFlags', value: flag.id });
          } else {
            seenFlagIds.add(flag.id);
          }
        }

        if (!flag.slug || typeof flag.slug !== 'string') {
          errors.push({ path: at('slug'), message: 'slug is required and must be a string', value: flag.slug });
        } else if (encodeURIComponent(flag.slug) !== flag.slug) {
          // Every route addresses a flag by slug in the URL path, so a slug that needs
          // percent-encoding seeds fine and is then unreachable.
          errors.push({
            path: at('slug'),
            message: 'slug must be URL-safe (no spaces, slashes or characters that need percent-encoding)',
            value: flag.slug,
          });
        } else if (seenSlugs.has(flag.slug)) {
          // Every lookup is by slug, so a duplicate is a flag no route can ever resolve.
          errors.push({ path: at('slug'), message: 'slug must be unique across featureFlags', value: flag.slug });
        } else {
          seenSlugs.add(flag.slug);
        }

        for (const field of ['enabled', 'default_value'] as const) {
          if (flag[field] !== undefined && typeof flag[field] !== 'boolean') {
            errors.push({ path: at(field), message: `${field} must be a boolean if provided`, value: flag[field] });
          }
        }

        if (flag.tags !== undefined && (!Array.isArray(flag.tags) || !flag.tags.every((t) => typeof t === 'string'))) {
          errors.push({ path: at('tags'), message: 'tags must be an array of strings if provided', value: flag.tags });
        }

        // `name` and `description` are passed through to the spec's Flag object verbatim, where
        // both are typed. A YAML scalar that happens to parse as a number would otherwise be
        // served as a type the real API never sends.
        if (flag.name !== undefined && typeof flag.name !== 'string') {
          errors.push({ path: at('name'), message: 'name must be a string if provided', value: flag.name });
        }
        if (flag.description !== undefined && flag.description !== null && typeof flag.description !== 'string') {
          errors.push({
            path: at('description'),
            message: 'description must be a string or null if provided',
            value: flag.description,
          });
        }

        if (flag.owner !== undefined && flag.owner !== null) {
          const ownerEmail = seedEmail(flag.owner.email);
          if (!ownerEmail.ok) {
            errors.push({
              path: at('owner.email'),
              message:
                ownerEmail.problem === 'malformed'
                  ? 'owner.email must be a valid email address'
                  : 'owner.email is required and must be a string',
              value: flag.owner.email,
            });
          }
          for (const part of ['first_name', 'last_name'] as const) {
            const value = flag.owner[part];
            if (value !== undefined && value !== null && typeof value !== 'string') {
              errors.push({
                path: at(`owner.${part}`),
                message: `owner.${part} must be a string or null if provided`,
                value,
              });
            }
          }
        }

        const targets = flag.targets;
        if (targets !== undefined && (typeof targets !== 'object' || targets === null || Array.isArray(targets))) {
          errors.push({ path: at('targets'), message: 'targets must be an object if provided', value: targets });
          return;
        }

        // Guarded before iterating: a scalar under `targets.users` would otherwise throw a raw
        // TypeError out of validateSeedConfig instead of reporting a validation error.
        for (const field of ['users', 'organizations'] as const) {
          const value = targets?.[field];
          if (value !== undefined && !Array.isArray(value)) {
            errors.push({
              path: at(`targets.${field}`),
              message: `targets.${field} must be an array if provided`,
              value,
            });
          }
        }

        const targetUsers = Array.isArray(targets?.users) ? targets.users : [];
        const targetOrgs = Array.isArray(targets?.organizations) ? targets.organizations : [];

        const seenTargetUsers = new Set<string>();
        targetUsers.forEach((email, i) => {
          const parsed = seedEmail(email);
          if (!parsed.ok) {
            errors.push({
              path: at(`targets.users[${i}]`),
              message: 'targets.users entries must be email addresses of users defined in `users`',
              value: email,
            });
            return;
          }
          const normalized = parsed.email.toLowerCase();
          if (!userEmails.has(normalized)) {
            errors.push({
              path: at(`targets.users[${i}]`),
              message: 'targets.users references an email not defined in `users`',
              value: email,
            });
          } else if (seenTargetUsers.has(normalized)) {
            // Two rows for one resource: removing the target over the API deletes only the
            // first match, so the flag would stay on for a user the caller just untargeted.
            errors.push({
              path: at(`targets.users[${i}]`),
              message: 'targets.users lists the same user twice',
              value: email,
            });
          } else {
            seenTargetUsers.add(normalized);
          }
        });

        const seenTargetOrgs = new Set<string>();
        targetOrgs.forEach((name, i) => {
          if (typeof name !== 'string') {
            errors.push({
              path: at(`targets.organizations[${i}]`),
              message: 'targets.organizations entries must be names of organizations defined in `organizations`',
              value: name,
            });
            return;
          }
          if (!orgNames.has(name)) {
            errors.push({
              path: at(`targets.organizations[${i}]`),
              message: 'targets.organizations references a name not defined in `organizations`',
              value: name,
            });
          } else if (seenTargetOrgs.has(name)) {
            errors.push({
              path: at(`targets.organizations[${i}]`),
              message: 'targets.organizations lists the same organization twice',
              value: name,
            });
          } else {
            seenTargetOrgs.add(name);
          }
        });
      });
    }
  }

  // Validate agent blueprints with the same checks the create route applies, so a seeded
  // blueprint production would have rejected fails the boot instead of minting oddly.
  if (config.agentBlueprints) {
    if (!Array.isArray(config.agentBlueprints)) {
      errors.push({
        path: 'agentBlueprints',
        message: 'agentBlueprints must be an array',
        value: config.agentBlueprints,
      });
    } else {
      const orgNames = new Set(
        Array.isArray(config.organizations)
          ? config.organizations.map((o) => o.name).filter((n): n is string => typeof n === 'string')
          : [],
      );
      const permissionSlugs = new Set(
        Array.isArray(config.permissions)
          ? config.permissions.map((p) => p.slug).filter((s): s is string => typeof s === 'string')
          : [],
      );
      const roleSlugs = new Set(
        Array.isArray(config.roles)
          ? config.roles.map((r) => r.slug).filter((s): s is string => typeof s === 'string')
          : [],
      );
      const seenNames = new Set<string>();
      const seenIds = new Set<string>();

      config.agentBlueprints.forEach((blueprint, index) => {
        const at = (field: string) => `agentBlueprints[${index}].${field}`;

        if (blueprint === null || typeof blueprint !== 'object' || Array.isArray(blueprint)) {
          errors.push({
            path: `agentBlueprints[${index}]`,
            message: 'each agent blueprint must be an object',
            value: blueprint,
          });
          return;
        }

        if (blueprint.id !== undefined) {
          if (typeof blueprint.id !== 'string' || !PINNED_ID_PATTERN.test(blueprint.id)) {
            errors.push({
              path: at('id'),
              message: 'id must be a string of letters, numbers, hyphens or underscores if provided',
              value: blueprint.id,
            });
          } else if (seenIds.has(blueprint.id)) {
            errors.push({ path: at('id'), message: 'id must be unique across agentBlueprints', value: blueprint.id });
          } else {
            seenIds.add(blueprint.id);
          }
        }

        if (typeof blueprint.name !== 'string' || blueprint.name.length === 0 || blueprint.name.length > 255) {
          errors.push({
            path: at('name'),
            message: 'name is required and must be a string of 1 to 255 characters',
            value: blueprint.name,
          });
        } else if (seenNames.has(blueprint.name)) {
          errors.push({
            path: at('name'),
            message: 'name must be unique across agentBlueprints',
            value: blueprint.name,
          });
        } else {
          seenNames.add(blueprint.name);
        }

        if (
          blueprint.description !== undefined &&
          (typeof blueprint.description !== 'string' ||
            blueprint.description.length === 0 ||
            blueprint.description.length > 1000)
        ) {
          errors.push({
            path: at('description'),
            message: 'description must be a string of 1 to 1000 characters if provided',
            value: blueprint.description,
          });
        }

        if (blueprint.permissions !== undefined) {
          if (!Array.isArray(blueprint.permissions) || blueprint.permissions.length > 1000) {
            errors.push({
              path: at('permissions'),
              message: 'permissions must be an array of at most 1000 permission slugs if provided',
              value: blueprint.permissions,
            });
          } else {
            blueprint.permissions.forEach((slug, i) => {
              if (typeof slug !== 'string' || !permissionSlugs.has(slug)) {
                errors.push({
                  path: at(`permissions[${i}]`),
                  message: 'permissions references a slug not defined in `permissions`',
                  value: slug,
                });
              }
            });
          }
        }

        const invocableBy = blueprint.invocable_by;
        if (invocableBy !== undefined) {
          if (typeof invocableBy !== 'object' || invocableBy === null || Array.isArray(invocableBy)) {
            errors.push({
              path: at('invocable_by'),
              message: 'invocable_by must be an object if provided',
              value: invocableBy,
            });
          } else {
            if (invocableBy.role_slugs !== undefined) {
              if (!Array.isArray(invocableBy.role_slugs) || invocableBy.role_slugs.length > 100) {
                errors.push({
                  path: at('invocable_by.role_slugs'),
                  message: 'invocable_by.role_slugs must be an array of at most 100 role slugs if provided',
                  value: invocableBy.role_slugs,
                });
              } else {
                invocableBy.role_slugs.forEach((slug, i) => {
                  if (typeof slug !== 'string' || !roleSlugs.has(slug)) {
                    errors.push({
                      path: at(`invocable_by.role_slugs[${i}]`),
                      message: 'invocable_by.role_slugs references a slug not defined in `roles`',
                      value: slug,
                    });
                  }
                });
              }
            }
            if (invocableBy.organizations !== undefined) {
              if (!Array.isArray(invocableBy.organizations) || invocableBy.organizations.length > 1000) {
                errors.push({
                  path: at('invocable_by.organizations'),
                  message: 'invocable_by.organizations must be an array of at most 1000 organization names if provided',
                  value: invocableBy.organizations,
                });
              } else {
                invocableBy.organizations.forEach((name, i) => {
                  if (typeof name !== 'string' || !orgNames.has(name)) {
                    errors.push({
                      path: at(`invocable_by.organizations[${i}]`),
                      message: 'invocable_by.organizations references a name not defined in `organizations`',
                      value: name,
                    });
                  }
                });
              }
            }
          }
        }

        const settings = blueprint.session_settings;
        if (settings !== undefined) {
          if (typeof settings !== 'object' || settings === null || Array.isArray(settings)) {
            errors.push({
              path: at('session_settings'),
              message: 'session_settings must be an object if provided',
              value: settings,
            });
          } else {
            for (const key of Object.keys(
              AGENT_SESSION_SETTING_LIMITS,
            ) as (keyof typeof AGENT_SESSION_SETTING_LIMITS)[]) {
              const value = settings[key];
              const max = AGENT_SESSION_SETTING_LIMITS[key];
              if (value === undefined) {
                errors.push({
                  path: at(`session_settings.${key}`),
                  message: `session_settings.${key} is required when session_settings is provided`,
                  value,
                });
              } else if (!Number.isInteger(value) || value <= 0 || value > max) {
                errors.push({
                  path: at(`session_settings.${key}`),
                  message: `session_settings.${key} must be a positive integer of at most ${max}`,
                  value,
                });
              }
            }
          }
        }
      });
    }
  }

  // Validating the template here means `--validate-config` catches a broken one, rather
  // than leaving it to fail at the first sign-in.
  if (config.jwtTemplate !== undefined) {
    if (typeof config.jwtTemplate !== 'object' || config.jwtTemplate === null) {
      errors.push({
        path: 'jwtTemplate',
        message: 'must be an object with a content field',
        value: config.jwtTemplate,
      });
    } else {
      for (const problem of validateJwtTemplateContent(config.jwtTemplate.content)) {
        errors.push({ path: 'jwtTemplate.content', message: problem, value: config.jwtTemplate.content });
      }
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

export function formatValidationErrors(errors: ConfigValidationError[]): string {
  return errors
    .map((error) => {
      const valueStr = error.value !== undefined ? ` (got: ${JSON.stringify(error.value)})` : '';
      return `  - ${error.path}: ${error.message}${valueStr}`;
    })
    .join('\n');
}
